const axios = require('axios');

module.exports = function (RED) {
    "use strict";

    function EventNode(n) {
        RED.nodes.createNode(this, n);
        let node = this;
        // 接收从前端传过来的 URL 参数
        this.event_type = n.event_type;
        this.gridId = n.gridId;
        this.projectId = n.projectId;
        this.ip = n.ip;
        // 利用 setImmediate 在节点启动（即部署完成）后立即执行一次同步
        setImmediate(function () {
            node.emit("input", { _isDeployTrigger: true });
        });
        this.on("input", function (msg, send, done) {
            // 如果是由部署触发的同步逻辑
            if (msg._isDeployTrigger) {
                const rawFlow = [];
                // 遍历当前运行时中所有的节点（包含 Tab、配置节点等全量数据）
                RED.nodes.eachNode(function(nodeData) {
                    // 使用浅拷贝防止污染内存
                    rawFlow.push(Object.assign({}, nodeData));
                });
                // === 核心修改：过滤与清洗数据 ===
                const processedFlow = rawFlow.map(n => {
                    if (n.type === "Event") {
                        // 如果是 Event 节点，通过解构赋值剔除 gridId 和 ip
                        const { gridId, ip, projectId, ...rest } = n;
                        return rest;
                    }
                    // 其他类型的节点（tab, Action, Wait 等）直接原样返回
                    return n;
                });
                console.log(`>>> 检测到部署同步任务 | IP: ${node.ip} | GridId: ${node.gridId} | ProjectId: ${node.projectId}`);
                console.log(`>>> 节点数据: ${JSON.stringify(processedFlow)}`);
                // 从类型为 tab 的节点中获取应用名称和描述
                const tabNode = processedFlow.find(n => n.type === "tab") || {};
                // 组装请求体
                const requestBody = {
                    projectId: node.projectId ? parseInt(node.projectId) : null,
                    gridId: node.gridId,
                    appName: tabNode.label || "未命名应用",
                    description: tabNode.info || "",
                    flowJson: JSON.stringify(processedFlow),
                    ruleJson: ""
                };
                console.log(`>>> 请求体内容: ${JSON.stringify(requestBody)}`);
                axios.post(`http://${node.ip}:8080/api/taps/create`, requestBody, {
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    timeout: 120000
                })
                .then(res => {
                    // --- 成功反馈 ---
                    node.status({ fill: "green", shape: "dot", text: "应用创建成功" });
                    setTimeout(() => {
                        node.status({}); // 传入空对象即可清除状态文字和小圆点
                    }, 3000);
                    // 在编辑器顶部弹出成功通知
                    RED.comms.publish("notification", {
                        type: "success",
                        text: "应用创建成功！",
                        timeout: 3000
                    });
                    console.log(">>> 业务后端同步成功");
                })
                .catch(err => {
                    // --- 失败反馈 ---
                    node.status({ fill: "red", shape: "ring", text: "应用创建失败" });
                    // 失败提示建议保留久一点，比如 8 秒，方便排查问题
                    setTimeout(() => {
                        node.status({});
                    }, 8000);
                    // 在编辑器顶部弹出错误通知
                    RED.comms.publish("notification", {
                        type: "error",
                        text: "应用创建失败: " + err.message,
                        timeout: 3000
                    });
                    console.error(">>> 业务后端同步失败:", err.message);
                });
            }
            // 正常的业务消息流转
            msg = msg || {};
            msg.type = node.type;
            msg.event_type = node.event_type;
            msg.context = {
                gridId: node.gridId,
                ip: node.ip
            };
            send(msg);
            if (done) done();
        });
    }
    RED.nodes.registerType("Event", EventNode);
};